extern "C" void run(const void* input1,const void* input2,void* output,int n,int parameter,int threads)
{
    const uint32_t* a = (const uint32_t*)input1;
    uint32_t result = 0;
    for (int j = 0; j < parameter; j++) {
        int i = 0;
        for (; i + 1 < n; i += 2) {
            result += popcount_naive(a[i] ^ result);
